select r.slug,rr.entry_label from regattas r join admin_change_log l on l.entity_id=r.id and l.source='sail-result-2026-2026-10-22' and l.action='results.import_official_sailresult2026' join regatta_results rr on rr.regatta_id=r.id left join regatta_race_results s on s.regatta_result_id=rr.id group by r.id,rr.id having count(s.id)<>r.race_count or abs(rr.total_score-sum(s.score::double precision))>.001 or abs(rr.nett_score-sum(s.score::double precision) filter(where not s.discarded))>.001 or rr.verification_status<>'verified' or rr.evidence_url is null;
